fn generate_binding_path(expression: &Expr) -> String {
    let mut parts: Vec<String> = Vec::new();

    fn traverse(node: &Expr, parts: &mut Vec<String>) {
        match node {
            Expr::Ident(ident) => {
                // Skip 'this' prefix
                if ident.sym.as_ref() != "this" {
                    parts.insert(0, ident.sym.to_string());
                }
            }
            Expr::Member(member) => {
                if let MemberProp::Ident(prop) = &member.prop {
                    parts.insert(0, prop.sym.to_string());
                }
                traverse(&member.obj, parts);
            }
            _ => {}
        }
    }

    traverse(expression, &mut parts);
    parts.join(".")
}
